class Solution { public int countSymmetricIntegers(int low,int high){int answer=0;for(int value=low;value<=high;value++){String digits=Integer.toString(value);if(digits.length()%2==1)continue;int first=0,second=0,half=digits.length()/2;for(int i=0;i<half;i++){first+=digits.charAt(i)-'0';second+=digits.charAt(i+half)-'0';}if(first==second)answer++;}return answer;} }
